PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?var1 ?var2 ?var3Label
WHERE
  { { SELECT  ?var1 (SAMPLE(?var4) AS ?var2) ?var3Label
      WHERE
        {   { SELECT  (str(?var5) AS ?var1) (0 AS ?var4) ("_" AS ?var3Label)
              WHERE
                { BIND(year(?var6) AS ?var5)
                  ?var7  wdt:P31   wde:Q577 ;
                         wdt:P585  ?var6
                  { SELECT  (MIN(?var5) AS ?var8) (MAX(?var5) AS ?var9)
                    WHERE
                      { BIND(year(?var10) AS ?var5)
                        ?var11  wdt:P50   wde:Q25373499 ;
                                wdt:P577  ?var10
                      }
                  }
                  FILTER ( ( ?var5 >= ?var8 ) && ( ?var5 <= ?var9 ) )
                }
            }
          UNION
            { BIND(substr(?var12Label, 1, 20) AS ?var3Label)
              BIND(str(year(?var6)) AS ?var1)
              ?var11  wdt:P50     wde:Q25373499 ;
                      wdt:P1104   ?var4 ;
                      wdt:P577    ?var6 ;
                      rdfs:label  ?var12Label
              FILTER ( lang(?var12Label) = "en" )
            }
        }
      GROUP BY ?var1 ?var11 ?var3Label
      ORDER BY ASC(?var1)
    }
  }

