PREFIX  url:  <http://schema.org/>

SELECT DISTINCT  ?var1 ?var2 ?var3 ?var4 ?var5 (COUNT(DISTINCT ?var6) AS ?var7)
WHERE
  {   { ?var8  wdt:P106  wde:Q36180 }
    UNION
      { ?var8  wdt:P106  wde:Q482980 }
    UNION
      { ?var8  wdt:P106  wde:Q49757 }
    ?var8  wdt:P27   ?var9 ;
           wdt:P268  ?var3
      { ?var8  wdt:P1412  wde:Q150 }
    UNION
      { ?var8  wdt:P1412  wde:Q1473289 }
      { ?var8  wdt:P21  wde:Q6581072 }
    UNION
      { ?var8  wdt:P21  wde:Q1097630 }
    UNION
      { ?var8  wdt:P21  wde:Q1052281 }
    UNION
      { ?var8  wdt:P21  wde:Q2449503 }
    OPTIONAL
      { ?var8  wdt:P569  ?var10 }
    BIND(year(?var10) AS ?var4)
    OPTIONAL
      { ?var8  wdt:P570  ?var11 }
    BIND(year(?var11) AS ?var5)
    ?var6  url:about  ?var8
    OPTIONAL
      { ?var8  rdfs:label  ?var1
        FILTER ( lang(?var1) = "fr" )
      }
    OPTIONAL
      { ?var9  rdfs:label  ?var2
        FILTER ( lang(?var2) = "fr" )
      }
    FILTER ( ( ?var4 <= 1448 ) && ( ?var5 >= 1446 ) )
  }
GROUP BY ?var2 ?var1 ?var3 ?var4 ?var5
ORDER BY DESC(?var7)

